import { Order } from '../domain/Order';
import { OrderLine } from '../domain/OrderLine';
import { OrderRepository } from '../domain/OrderRepository';
import { Product } from '../domain/Product';
import { ProductRepository } from '../domain/ProductRepository';
import { NotFoundError } from './ApplicationErrors';

/** Loads aggregates for use cases, failing with NotFoundError when one is missing. */
export class EntityLookupService {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  requireOrder(orderId: string): Order {
    const order = this.orders.findById(orderId);
    if (order === undefined) {
      throw new NotFoundError('Order', orderId);
    }
    return order;
  }

  requireProductsFor(lines: readonly OrderLine[]): Map<string, Product> {
    const found = new Map<string, Product>();
    for (const line of lines) {
      const product = this.products.findById(line.productId);
      if (product === undefined) {
        throw new NotFoundError('Product', line.productId);
      }
      found.set(product.id, product);
    }
    return found;
  }
}

